package com.wokgui.guidevoyage;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import org.json.*;import java.net.*;import java.io.*;import java.util.zip.*;import java.nio.charset.StandardCharsets;
final class SiteUpdates {
 private static final String BASE="1903301aed7d80a602b4141ef0d5be3e54e2534e"; // Bundled page revision; refreshed snapshots come from the owner's main branch.
 private final Activity activity;private final android.content.SharedPreferences prefs;private File active;
 SiteUpdates(Activity a){activity=a;prefs=a.getSharedPreferences("site_updates",0);String pending=prefs.getString("pending",null);String current=prefs.getString("active",null);if(pending!=null&&valid(new File(a.getFilesDir(),"site-versions/"+pending))&&new File(a.getFilesDir(),"site-versions/"+pending+"/.complete").isFile()){current=pending;prefs.edit().putString("active",current).remove("pending").apply();}if(current!=null){File f=new File(a.getFilesDir(),"site-versions/"+current);if(valid(f))active=f;}}
 InputStream open(String path)throws IOException{if(path.equals("index.html")||path.equals("native-bootstrap.js")||path.equals("cloud-backup.js")||path.equals("shared-sync.js"))return activity.getAssets().open("site/"+path);if(active!=null){File f=new File(active,path);if(f.getCanonicalPath().startsWith(active.getCanonicalPath()+File.separator)&&f.isFile())return new FileInputStream(f);}return activity.getAssets().open("site/"+path);}
 void check(){prefs.edit().putLong("lastCheck",System.currentTimeMillis()).apply();new Thread(()->{checkApk();try{String sha=new JSONObject(new String(fetch("https://api.github.com/repos/Wokgui/Guide-de-voyage-Android/commits/main",2*1024*1024),StandardCharsets.UTF_8)).getString("sha");if(!sha.matches("[0-9a-f]{40}")||sha.equals(prefs.getString("active",BASE))||sha.equals(prefs.getString("pending",null)))return;File dir=new File(activity.getFilesDir(),"site-versions/"+sha);if(!(valid(dir)&&new File(dir,".complete").isFile())){
 byte[] zip=fetch("https://codeload.github.com/Wokgui/Guide-de-voyage-Android/zip/"+sha,64*1024*1024);dir.mkdirs();long total=0;int count=0;
 try(ZipInputStream zin=new ZipInputStream(new ByteArrayInputStream(zip))){ZipEntry e;byte[] buffer=new byte[16384];while((e=zin.getNextEntry())!=null){String n=e.getName();int slash=n.indexOf('/');if(slash<0)continue;n=n.substring(slash+1);if(e.isDirectory()||!allowed(n))continue;File f=new File(dir,n);if(!f.getCanonicalPath().startsWith(dir.getCanonicalPath()+File.separator))throw new IOException("Unsafe archive path");if(++count>5000)throw new IOException("Archive too large");f.getParentFile().mkdirs();try(OutputStream out=new FileOutputStream(f)){int read;while((read=zin.read(buffer))!=-1){total+=read;if(total>128*1024*1024)throw new IOException("Archive too large");out.write(buffer,0,read);}}}}
 if(!valid(dir))throw new IOException("Incomplete site update");new File(dir,".complete").createNewFile();
 }if(!new File(dir,".complete").isFile())return;prefs.edit().putString("pending",sha).apply();
 }catch(Exception ignored){prefs.edit().putString("lastError",ignored.toString()).apply();android.util.Log.w("GuideUpdates","Content update failed",ignored);}},"guide-site-update").start();}
 boolean shouldCheck(){return System.currentTimeMillis()-prefs.getLong("lastCheck",0)>6*60*60*1000L;}
 private boolean allowed(String n){if(n.contains("..")||n.startsWith(".")||n.startsWith("android-app/")||n.startsWith("api/")||n.startsWith("node_modules/"))return false;return n.matches(".*\\.(html|css|js|json|webmanifest|png|jpe?g|webp|svg|woff2?|ttf|ico)$")&&!n.equals("vercel.json")&&!n.startsWith("package");}
 private boolean valid(File d){return new File(d,"index.html").isFile()&&new File(d,"icons/app-icon-512.png").isFile()&&new File(d,"shared-sync.js").isFile();}
 private byte[] fetch(String address,int limit)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(15000);c.setRequestProperty("User-Agent","Wokgui-Guide-Android");c.setRequestProperty("Accept","application/vnd.github+json");try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[16384];int read;while((read=in.read(b))!=-1){if(out.size()+read>limit)throw new IOException("Download too large");out.write(b,0,read);}return out.toByteArray();}}finally{c.disconnect();}}
 private void checkApk(){try{
 JSONArray releases=new JSONArray(new String(fetch("https://api.github.com/repos/Wokgui/Guide-de-voyage-Android/releases?per_page=20",512*1024),StandardCharsets.UTF_8));
 android.content.pm.PackageInfo info=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0);
 String newest=info.versionName,url=null;
 for(int i=0;i<releases.length();i++){JSONObject release=releases.getJSONObject(i);if(release.optBoolean("draft")||release.optBoolean("prerelease"))continue;String tag=release.optString("tag_name");if(!tag.matches("android-v[0-9]+\\.[0-9]+(?:\\.[0-9]+)?"))continue;String version=tag.substring(9);if(compareVersions(version,newest)<=0)continue;JSONArray assets=release.optJSONArray("assets");if(assets==null)continue;for(int j=0;j<assets.length();j++){JSONObject asset=assets.getJSONObject(j);String expected="Guide-de-voyage-Android-"+version+".apk",candidate=asset.optString("browser_download_url");if(expected.equals(asset.optString("name"))&&candidate.equals("https://github.com/Wokgui/Guide-de-voyage-Android/releases/download/"+tag+"/"+expected)){newest=version;url=candidate;break;}}}
 if(url==null)return;final String selectedUrl=url;
 activity.runOnUiThread(()->{if(!activity.isFinishing()&&!activity.isDestroyed())new AlertDialog.Builder(activity).setTitle("Mise à jour de Guide de voyage").setMessage("Une nouvelle version est disponible. Télécharge le fichier, puis ouvre-le et choisis Mettre à jour. Tes données sont conservées.").setPositiveButton("Télécharger",(d,w)->activity.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(selectedUrl)))).setNegativeButton("Plus tard",null).show();});
 }catch(Exception ignored){}}
 static int compareVersions(String left,String right){String[] a=left.split("\\."),b=right.split("\\.");for(int i=0;i<Math.max(a.length,b.length);i++){int x=i<a.length?Integer.parseInt(a[i]):0,y=i<b.length?Integer.parseInt(b[i]):0;if(x!=y)return Integer.compare(x,y);}return 0;}
}
